const ref=n=>`<a href="#ref-${n}" class="ref-link"><sup>[${n}]</sup></a>`;
function replaceOnce(s,re,v,label){let n=0;const out=s.replace(re,(...args)=>{n++;return typeof v==='function'?v(...args):v;});if(n!==1)throw Error(`${label}: expected one match, got ${n}`);return out;}
const escape=s=>s.replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;');
const sha=s=>crypto.createHash('sha256').update(s).digest('hex');
const manifest={generated_at:new Date().toISOString(),scope:'existing 156 sitemap URLs; 0006 topic only',status:'DRAFT_NOT_RELEASED',files:[]};
for(const r of rows){
 const fn=`0006.back-pain-lying${r.suffix}.html`,rel=`encyclopedia/${fn}`,url=`https://wiki.body-all.co.kr/${rel}`;
 const source=fs.readFileSync(path.join(root,'source',rel),'utf8');let s=source;
