 s=s.replace(/(<meta\b[^>]*property\s*=\s*["']og:url["'][^>]*content\s*=\s*)["'][^"']*["']/g,`$1"${url}"`);
 s=replaceOnce(s,/<meta name="viewport"[^>]*>/,'<meta name="viewport" content="width=device-width, initial-scale=1.0">','viewport');
 s=s.replace(/<meta name=["']robots["'][^>]*>\s*/g,'');s=s.replace('</title>','</title>\n    <meta name="robots" content="index, follow">');
 const schemaRE=/<script type="application\/ld\+json">([\s\S]*?)<\/script>/;const graph=JSON.parse(s.match(schemaRE)[1]);
 const webpage=graph['@graph'].find(x=>x['@type']==='MedicalWebPage');Object.assign(webpage,{name:r.h1,url,inLanguage:r.lang,description:r.description});webpage.about={ '@type':'MedicalCondition',name:r.condition};
 const clinic=graph['@graph'].find(x=>[].concat(x['@type']).includes('MedicalClinic'));
 delete clinic.isAcceptingNewPatients;delete clinic.priceRange;delete clinic.paymentAccepted;
 // These old strings are not the MedicalSpecialty enumeration; do not imply
