 const procedure=graph['@graph'].find(x=>x['@type']==='MedicalProcedure');procedure.description=r.lang==='ko'?'진찰 결과에 따라 적용 여부와 강도를 정하고 같은 움직임을 재평가하는 바디올의 추나 진료 프로토콜.':r.lang==='en'?'Bodyall’s Chuna care protocol: suitability and intensity are selected after assessment, followed by reassessment of the same movement.':'Bodyall的推拿诊疗方案：评估后决定适用性与强度，再复测同一动作。';
 // TherapeuticProcedure is a class, not a MedicalProcedureType value.
 delete procedure.procedureType;
 procedure.url=`https://wiki.body-all.co.kr/SART${r.suffix}.html`;
 let faq=graph['@graph'].find(x=>x['@type']==='FAQPage');if(!faq){faq={'@type':'FAQPage','@id':url+'#faq'};graph['@graph'].push(faq);}faq.mainEntity=r.faq.map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}));
 s=replaceOnce(s,schemaRE,`<script type="application/ld+json">\n${JSON.stringify(graph,null,2)}\n</script>`,'schema');
 const faqHTML=`<section id="faq"><h2>${r.faqTitle}</h2>${r.faq.map(([q,a])=>`<div class="solution-card"><h3>${q}</h3><p>${a}</p></div>`).join('\n')}</section>`;
 const appointment=`<section class="solution-card" id="appointment"><h2>${r.appointmentTitle}</h2><p>${r.appointment}</p><p>${r.hours}${ref(6)}</p><p><a class="treatment-link" href="https://naver.me/53lcJrXB">${r.book} →</a> · <a href="tel:+823180675825">${r.call}: 031-8067-5825</a></p></section>`;
 const main=`<main class="ba-article-content">\n<div class="breadcrumb">${r.crumb}</div>\n<h1>${r.h1}</h1>\n<article>\n${r.intro}\n<img src="./image/0006.back-pain-lying-main.png" alt="${r.alt}" class="hero-img" loading="eager" decoding="async" width="2656" height="1600">\n${r.sections.join('\n')}\n${faqHTML}\n${appointment}\n</article>\n</main>`;
 s=replaceOnce(s,/<main class="ba-article-content">[\s\S]*?<\/main>/,main,'main');
 const references=`<div class="references-section"><h2>${r.refsTitle}</h2><ol>
<li id="ref-1">Yuk DI et al. (2013). <a href="https://pubmed.ncbi.nlm.nih.gov/25780675/">Clinical study of lumbar spine stenosis treated by using acupotomy combined with oriental medical treatments</a>. J Pharmacopuncture. 16(3):46–51.</li>
<li id="ref-2">Kang H et al. (2025). <a href="https://doi.org/10.18325/jkmr.2025.35.4.69">Effects of Acupotomy Treatment for Lumbar Spinal Stenosis: A Systematic Review and Meta Analysis</a>. J Korean Med Rehabil. 35(4):69–83.</li>
<li id="ref-3">NHS. <a href="https://www.nhs.uk/conditions/back-pain/">Back pain: causes, self-care and when to get medical help</a>.</li>
<li id="ref-4">NICE NG59 (updated 2020). <a href="https://www.ncbi.nlm.nih.gov/books/NBK562933/">Low back pain and sciatica in over 16s: assessment and management</a>.</li>
<li id="ref-5">NCCIH. <a href="https://www.nccih.nih.gov/health/spinal-manipulation-what-you-need-to-know">Spinal Manipulation: What You Need To Know</a>.</li>
<li id="ref-6"><a href="../index${r.suffix}.html">${r.clinicRef}</a> · <a href="https://body-all.co.kr">body-all.co.kr</a>.</li>
</ol></div>`;
 s=replaceOnce(s,/<div class=['"]references-section['"]>[\s\S]*?<\/ol><\/div>/,references,'references');
 s=s.replace('href="./index.html" class="back-btn"',`href="./index${r.suffix}.html" class="back-btn"`);
 s=s.replace(/📍 365(?:일 진료 및 상담| Days Care & Consultation|天[\s\S]*?(?=<\/h2>))/g,`📍 ${r.footer}`);
 s=s.replace(/<a\b[^>]*target=["']_blank["'][^>]*>/g,x=>x.includes('rel=')?x:x.slice(0,-1)+' rel="noopener noreferrer">');
 s=s.replace('http://talk.naver.com','https://talk.naver.com');
 s=s.replace('</style>','/* Layout safeguards for long translations and reserved image dimensions. */\n        .wrapper, .ba-article-content, .references-section { overflow-wrap: anywhere; }\n        .ba-article-content img { height: auto; }\n        .map-link-btn { box-sizing: border-box; max-width: 100%; }\n        section[id] { scroll-margin-top: 80px; }\n    </style>');
 const output=path.join(root,'candidate',rel);fs.mkdirSync(path.dirname(output),{recursive:true});fs.writeFileSync(output,s);
 manifest.files.push({path:rel,source_sha256:sha(source),candidate_sha256:sha(s),type:'article'});
 const indexRel=`encyclopedia/index${r.suffix}.html`;const idxSource=fs.readFileSync(path.join(root,'source',indexRel),'utf8');
 const cardRE=new RegExp('<li class="symptom-item">(?:(?!<li)[\\s\\S])*?href="\\./'+fn.replaceAll('.','\\.')+'"[\\s\\S]*?</li>','g');
 const idx=replaceOnce(idxSource,cardRE,card=>card.replace(/(<a[^>]+class="q-title">)[\s\S]*?(<\/a>)/,`$1${r.card}$2`).replace(/(<div class="hash-tags">)[\s\S]*?(<span class="date-info">)/,`$1\n        ${r.tags} $2`),'index card');
 fs.writeFileSync(path.join(root,'candidate',indexRel),idx);manifest.files.push({path:indexRel,source_sha256:sha(idxSource),candidate_sha256:sha(idx),type:'card_only'});
}
fs.writeFileSync(path.join(root,'candidate_manifest.json'),JSON.stringify(manifest,null,2)+'\n');
console.log(JSON.stringify(manifest,null,2));

