"""Dependency-free preflight and fail-closed exact-candidate release gate.

Usage: python check_release.py [--release RECEIPT.json] [--self-test]
No GitHub writes or browser control. Preflight PASS is never a release PASS.
"""
from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit
import hashlib, json, re, sys, copy, struct

ROOT = Path(__file__).resolve().parent
BASE = 'https://wiki.body-all.co.kr/'
VOID = set('area base br col embed hr img input link meta param source track wbr'.split())

class Element:
    def __init__(self, tag, attrs=(), parent=None):
        self.tag, self.attrs, self.parent, self.children = tag, dict(attrs), parent, []
    def text(self):
        return ''.join(c.text() if isinstance(c, Element) else c for c in self.children)
    def all(self, tag=None):
        for c in self.children:
            if isinstance(c, Element):
                if tag is None or c.tag == tag: yield c
                yield from c.all(tag)

class Document(HTMLParser):
    def __init__(self, html):
        super().__init__(convert_charrefs=True)
        self.root=Element('root'); self.stack=[self.root]; self.errors=[]
        self.feed(html); self.close()
        if len(self.stack)>1: self.errors.append('unclosed: '+str([n.tag for n in self.stack[1:]]))
    def handle_starttag(self,tag,attrs):
        n=Element(tag,attrs,self.stack[-1]); self.stack[-1].children.append(n)
        if len(attrs)!=len(dict(attrs)): self.errors.append('duplicate attribute '+tag)
        if tag not in VOID:self.stack.append(n)
    def handle_startendtag(self,tag,attrs):
        self.handle_starttag(tag,attrs)
        if tag not in VOID:self.handle_endtag(tag)
    def handle_endtag(self,tag):
        if self.stack[-1].tag==tag:self.stack.pop()
        else:self.errors.append('mismatched closing '+tag+' after '+self.stack[-1].tag)
    def handle_data(self,data):self.stack[-1].children.append(data)
    def all(self,tag=None):return list(self.root.all(tag))

def norm(t): return re.sub(r'\s+',' ',t).strip()
def digest(text): return hashlib.sha256(text.encode()).hexdigest()

def preflight():
    manifest=json.loads((ROOT/'candidate_manifest.json').read_text()); reports=[]
    sitemap=Document((ROOT/'source/sitemap.xml').read_text())
    locations=[x.text() for x in sitemap.all('loc')]
    for item in manifest['files']:
        rel=item['path'];s=(ROOT/'candidate'/rel).read_bytes().decode('utf-8');source=(ROOT/'source'/rel).read_bytes().decode('utf-8')
        errors=[];d=Document(s)
        if digest(s)!=item['candidate_sha256']:errors.append('manifest hash stale')
        if digest(source)!=item['source_sha256']:errors.append('source hash stale')
        if item['type']=='card_only':
            # Everything except the one existing 0006 card must be byte-identical.
            pat=r'<li class="symptom-item">(?:(?!<li)[\s\S])*?href="\./0006\.back-pain-lying[^"\s]*"[\s\S]*?</li>'
            if len(re.findall(pat,s))!=1 or len(re.findall(pat,source))!=1: errors.append('card count')
            if re.sub(pat,'CARD',s)!=re.sub(pat,'CARD',source):errors.append('unrelated index edits')
            reports.append({'path':rel,'sha256':digest(s),'errors':errors,'scope':'one existing card'});continue
        errors+=d.errors
        suffix='_en' if '_en.html' in rel else '_cn' if '_cn.html' in rel else ''
        lang={'':'ko','_en':'en','_cn':'zh-Hans'}[suffix];url=BASE+rel
        if url not in locations:errors.append('not in existing sitemap')
        for t in ('html','head','body','main','h1','title'):
            if len(d.all(t))!=1:errors.append('expected exactly one '+t)
        if d.all('html')[0].attrs.get('lang')!=lang:errors.append('lang')
        metas={n.attrs.get('name',n.attrs.get('property')):n.attrs.get('content') for n in d.all('meta')}
        if metas.get('robots')!='index, follow':errors.append('robots')
        if metas.get('og:url')!=url:errors.append('og url')
        if metas.get('og:title')!=d.all('title')[0].text():errors.append('og title mismatch')
        if metas.get('description')!=metas.get('og:description') or not metas.get('description'):errors.append('description mismatch')
        if metas.get('viewport')!='width=device-width, initial-scale=1.0':errors.append('viewport/zoom')
        links=[n.attrs for n in d.all('link')]
        if [a.get('href') for a in links if a.get('rel')=='canonical']!=[url]:errors.append('canonical')
        expected_alts={('ko',BASE+'encyclopedia/0006.back-pain-lying.html'),('en',BASE+'encyclopedia/0006.back-pain-lying_en.html'),('zh-Hans',BASE+'encyclopedia/0006.back-pain-lying_cn.html'),('x-default',BASE+'encyclopedia/0006.back-pain-lying.html')}
        if {(a.get('hreflang'),a.get('href')) for a in links if a.get('rel')=='alternate'}!=expected_alts:errors.append('hreflang')
        ids=[n.attrs['id'] for n in d.all() if 'id' in n.attrs]
        if len(ids)!=len(set(ids)):errors.append('duplicate ids')
        for a in d.all('a'):
            href=a.attrs.get('href','')
            if not href:errors.append('empty href')
            if href.startswith('#') and href[1:] not in ids:errors.append('missing fragment '+href)
            if a.attrs.get('target')=='_blank' and not {'noopener','noreferrer'}<=set(a.attrs.get('rel','').split()):errors.append('unsafe external target')
        back=[a.attrs['href'] for a in d.all('a') if 'back-btn' in a.attrs.get('class','')]
        if back!=['./index'+suffix+'.html']:errors.append('same-language back')
        imgs=d.all('img')
        if len(imgs)!=1:errors.append('unexpected image count')
        if any(i.attrs.get('width')!='2656' or i.attrs.get('height')!='1600' or not i.attrs.get('alt') for i in imgs):errors.append('image dimensions/alt')
        for img in imgs:
            asset=ROOT/'assets'/img.attrs.get('src','').split('/')[-1]
            raw=asset.read_bytes() if asset.exists() else b''
            if len(raw)<24 or raw[:8]!=b'\x89PNG\r\n\x1a\n':
                errors.append('image bytes not available for verification: '+str(asset.name))
            elif struct.unpack('>II',raw[16:24])!=(int(img.attrs['width']),int(img.attrs['height'])):
                errors.append('image reserved size does not match PNG: '+str(asset.name))
        if '0006.back-pain-mechanism' in s:errors.append('rejected illustration still present')
        schemas=[n.text() for n in d.all('script') if n.attrs.get('type')=='application/ld+json']
        if len(schemas)!=1:errors.append('schema count')
        try:
            graph=json.loads(schemas[0])['@graph'];wp=next(n for n in graph if n.get('@type')=='MedicalWebPage');faq=next(n for n in graph if n.get('@type')=='FAQPage')['mainEntity']
            for entity in graph:
                if entity.get('procedureType')=='TherapeuticProcedure':errors.append('invalid procedureType enumeration')
                if any(x in ('TraditionalChineseMedicine','Acupuncture') for x in entity.get('medicalSpecialty',[])):errors.append('invalid medicalSpecialty enumeration')
            if wp.get('url')!=url or wp.get('inLanguage')!=lang:errors.append('schema locale')
            if wp['name']!=d.all('h1')[0].text():errors.append('schema heading')
            if len(faq)!=3:errors.append('faq count')
            visible=norm(d.all('main')[0].text())
            for q in faq:
                if norm(q['name']) not in visible or norm(q['acceptedAnswer']['text']) not in visible:errors.append('FAQ not in visible main')
        except (ValueError,KeyError,StopIteration,IndexError) as exc: errors.append('schema '+str(exc))
        if re.search(r'reviewedBy|lastReviewed',s):errors.append('unauthorized new physician attestation')
        for bad in ('신경 조직 주변 유착 박리 및 척추 구조 개선 메커니즘','safe.*prior to surgery','physically securing space','안전하고 효과적인 비수술적','365 Days','365일','365天'):
            if re.search(bad,s):errors.append('rejected claim '+bad)
        required={'ko':['수원','바디올','근막이완 추나','SART','같은 동작','119','아나필락시스'],'en':['Suwon','Bodyall','myofascial-release Chuna','SART','same movement','119','anaphylaxis'],'zh-Hans':['水原','Bodyall','筋膜放松推拿','SART','同一动作','119','过敏性休克']}[lang]
        for word in required:
            if word not in s:errors.append('missing topic concept '+word)
        for i in range(1,7):
            if f'ref-{i}' not in ids or not any(a.attrs.get('href')==f'#ref-{i}' for a in d.all('a')):errors.append('reference unused/missing '+str(i))
        reports.append({'path':rel,'sha256':digest(s),'errors':errors,'images':len(imgs),'full_html_parsed':True})
    return {'stage':'STATIC_ONLY','release_permitted':False,'reports':reports,'errors':sum(len(r['errors']) for r in reports)}

def release_errors(receipt, hashes):
    errors=[]
    if receipt.get('decision')!='PASS':errors.append('editor decision is not PASS')
    if receipt.get('unresolved_defects')!=[]:errors.append('unresolved defects or absent defect list')
    if receipt.get('exact_candidate_sha256')!=hashes:errors.append('missing/stale exact-candidate review')
    for key in ('complete_html_read','medical_claims_reviewed','clinic_provenance_reviewed','translations_aligned','recommendation_reason_recorded','approval_scope_preserved','static_checks_passed'):
        if receipt.get(key) is not True:errors.append('missing '+key)
    visual=receipt.get('render_review',{})
    for rel in hashes:
        views=visual.get(rel,{})
        for mode in ('desktop','narrow'):
            result=views.get(mode,{})
            if result.get('inspected') is not True or result.get('candidate_sha256')!=hashes[rel] or not result.get('evidence'):
                errors.append(rel+': missing exact '+mode+' render evidence')
    return errors

def self_test(hashes):
    r={'decision':'PASS','unresolved_defects':[],'exact_candidate_sha256':hashes.copy(),'render_review':{}}
    for key in ('complete_html_read','medical_claims_reviewed','clinic_provenance_reviewed','translations_aligned','recommendation_reason_recorded','approval_scope_preserved','static_checks_passed'):r[key]=True
    for rel,h in hashes.items():
        r['render_review'][rel]={mode:{'inspected':True,'candidate_sha256':h,'evidence':'SYNTHETIC TEST FIXTURE ONLY'} for mode in ('desktop','narrow')}
    assert not release_errors(r,hashes)
    bad=copy.deepcopy(r);bad['exact_candidate_sha256'][next(iter(hashes))]='stale';assert release_errors(bad,hashes)
    bad=copy.deepcopy(r);bad['render_review']={};assert release_errors(bad,hashes)
    bad=copy.deepcopy(r);bad['unresolved_defects']=['factual error'];assert release_errors(bad,hashes)
    bad=copy.deepcopy(r);bad['translations_aligned']=False;assert release_errors(bad,hashes)
    assert release_errors({},hashes)
    return 'PASS: synthetic positive + stale hash, missing renders, open defect, incomplete translation, absent receipt all blocked'

if __name__=='__main__':
    result=preflight();hashes={r['path']:r['sha256'] for r in result['reports']}
    if '--self-test' in sys.argv:result['gate_self_test']=self_test(hashes)
    if '--release' in sys.argv:
        receipt=json.loads(Path(sys.argv[sys.argv.index('--release')+1]).read_text())
        result['release_errors']=release_errors(receipt,hashes)
        result['release_permitted']=not result['errors'] and not result['release_errors']
    print(json.dumps(result,ensure_ascii=False,indent=2))
    sys.exit(1 if result['errors'] or result.get('release_errors') else 0)

