import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
const root=path.dirname(new URL(import.meta.url).pathname);
const snapshot=JSON.parse(fs.readFileSync(path.join(root,'source_snapshot.json'),'utf8'));
for(const [rel,record] of Object.entries(snapshot.files)){
 const bytes=Buffer.from(record.content,'utf8');
 const blob=crypto.createHash('sha1').update(`blob ${bytes.length}\0`).update(bytes).digest('hex');
 if(blob!==record.sha)throw Error('Remote snapshot not byte-exact '+rel);
 // Mechanical restoration of remote bytes, including original mixed CRLF and EOF whitespace.
 fs.writeFileSync(path.join(root,'source',rel),bytes);
 console.log(rel+' '+blob);
}
